<?php require '../includes/config.php';admin_only();$adminTitle='Branches';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['action'];if($act==='save'){$id=(int)($_POST['id']??0);$v=[trim($_POST['name']),trim($_POST['city']),trim($_POST['address']),trim($_POST['phone']),trim($_POST['email']),trim($_POST['hours']),isset($_POST['active'])?1:0];if($id){$v[]=$id;$pdo->prepare('UPDATE branches SET name=?,city=?,address=?,phone=?,email=?,hours=?,active=? WHERE id=?')->execute($v);}else{$pdo->prepare('INSERT INTO branches(name,city,address,phone,email,hours,active) VALUES(?,?,?,?,?,?,?)')->execute($v);}}else{$pdo->prepare('DELETE FROM branches WHERE id=?')->execute([(int)$_POST['id']]);}header('Location:branches.php');exit;}$rows=$pdo->query('SELECT * FROM branches ORDER BY city,name')->fetchAll();$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM branches WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}include '_top.php';?><h1 class="title">Branches</h1><div class="row g-4"><div class="col-xl-4"><div class="table-card"><h4><?=$edit?'Edit':'Add'?> Branch</h4><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']??''?>"><?php foreach(['name'=>'Branch name','city'=>'City','address'=>'Address','phone'=>'Phone','email'=>'Email','hours'=>'Opening hours'] as $n=>$p):?><input required name="<?=$n?>" value="<?=e($edit[$n]??'')?>" class="form-control mb-2" placeholder="<?=$p?>"><?php endforeach;?><label><input type="checkbox" name="active" <?=!isset($edit['active'])||$edit['active']?'checked':''?>> Active</label><button class="btn btn-primary w-100 mt-3">Save Branch</button></form></div></div><div class="col-xl-8"><div class="table-card table-responsive"><table class="table"><tr><th>Name</th><th>City</th><th>Phone</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['city'])?></td><td><?=e($r['phone'])?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">Edit</a><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></table></div></div></div><?php include '_bottom.php';?>